        private void Start()
        {
            Application.runInBackground = true;

            CheckAutoLogin();

            //if (!string.IsNullOrEmpty(PlayerPrefs.GetString("LoginToken")))
            //{
            //    Debug.Log("UserLoginManager.Start(): WalletAddress: " + APIManager.WalletAddress);
            //}
        }

        private async void CheckAutoLogin()
        {
            if (!string.IsNullOrEmpty(BD.APIManager.AUTH_TOKEN) && !string.IsNullOrEmpty(BD.APIManager.WalletAddress))
            {
                loginButton.interactable = false;

                // check if login token is still valid
                await BD.APIManager.CheckDeviceID(CheckDeviceIDResult);

                void CheckDeviceIDResult(bool apiSuccess, bool deviceExists)
                {
                    if (!apiSuccess)
                    {
                        Debug.LogError("<color=cyan>UserLoginManager</color> Failed to verify user login status.");
                        loginButton.interactable = true;
                        return;
                    }
                    if (!deviceExists)
                    {
                        Debug.LogError("<color=cyan>UserLoginManager</color> Login status is invalid. Logging out...");
                        _ = BD.APIManager.LogOutAsync();
                        loginButton.interactable = true;
                        return;
                    }

                    Debug.Log("<color=cyan>UserLoginManager</color> Already logged in. Proceeding to home screen...");
                    _ = BD.APIManager.GetUserDetailsByWallet();
                    _ = BD.NFTManager.GetNFTs(BD.APIManager.WalletAddress);
                    LoadMainMenuScene();
                }
            }
            else
            {
                loginButton.interactable = true;
            }
        }

        internal static async void LoadMainMenuScene()
        {
            Instance.StartCoroutine(Instance.ContinuousLoginStatusCheck());
            await System.Threading.Tasks.Task.Delay(500);
            SceneManager.LoadScene("Demo_Fighter3D - Type 2");
        }


