        private IEnumerator ContinuousLoginStatusCheck()
        {
            while (true)
            {
                yield return new WaitForSeconds(60);

                yield return BD.APIManager.CheckDeviceID((apiSuccess, deviceExists) =>
                {
                    if (!apiSuccess)
                    {
                        Debug.LogError("<color=cyan>UserLoginManager</color> Failed to verify user login status.");
                        return;
                    }

                    if (deviceExists)
                    {
                        Debug.Log("<color=cyan>UserLoginManager</color> Login status is still valid.");
                    }
                    else
                    {
                        Debug.LogError("<color=cyan>UserLoginManager</color> Login status is invalid. Logging out...");
                        _ = BD.APIManager.LogOutAsync();
                    }
                });
            }
        }
    }
